  'ps.tab_payments':'ಪಾವತಿಗಳು',
  'ps.tab_admins':'ಪ್ಲಾಟ್‌ಫಾರ್ಮ್ ನಿರ್ವಾಹಕರು',
  'ps.tab_health':'ಆರೋಗ್ಯ',
  'ps.tab_maintenance':'ನಿರ್ವಹಣೆ',
  'ps.maint_title':'ನಿರ್ವಹಣಾ ಮೋಡ್',
  'ps.maint_hint':'ನವೀಕರಣದ ಕೆಲಸ ಮಾಡುವಾಗ ಇಡೀ ಪ್ಲಾಟ್‌ಫಾರ್ಮ್ ಅನ್ನು ತಡೆಹಿಡಿಯುತ್ತದೆ. ಪ್ರತಿ ಸಂಸ್ಥೆಯೂ ಲಾಕ್ ಆಗುತ್ತದೆ — ಯಾರೂ ಸೈನ್ ಇನ್ ಮಾಡಲಾಗುವುದಿಲ್ಲ, ಮತ್ತು ಈಗಾಗಲೇ ತೆರೆದಿರುವ ಸೆಷನ್‌ಗಳು ಮುಂದಿನ ವಿನಂತಿಯಲ್ಲಿ ನಿಲ್ಲುತ್ತವೆ. IFQM ಪ್ಲಾಟ್‌ಫಾರ್ಮ್ ಅಡ್ಮಿನ್ ಖಾತೆಗಳಿಗೆ ಪರಿಣಾಮ ಬೀರುವುದಿಲ್ಲ, ಆದ್ದರಿಂದ ನೀವು ಕೆಲಸ ಮುಂದುವರಿಸಬಹುದು ಮತ್ತು ಇದೇ ಪರದೆಯಿಂದ ಇದನ್ನು ಆಫ್ ಮಾಡಬಹುದು.',
  'ps.maint_state_on':'ನಿರ್ವಹಣಾ ಮೋಡ್ ಆನ್ ಆಗಿದೆ — ಎಲ್ಲಾ ಟೆನೆಂಟ್‌ಗಳು ಲಾಕ್ ಆಗಿವೆ',
  'ps.maint_state_off':'ನಿರ್ವಹಣಾ ಮೋಡ್ ಆಫ್ ಆಗಿದೆ — ಪ್ಲಾಟ್‌ಫಾರ್ಮ್ ಚಾಲನೆಯಲ್ಲಿದೆ',
  'ps.maint_since':'{when} ರಿಂದ ತಡೆಹಿಡಿಯಲಾಗಿದೆ',
