  'ps.maint_message_hint':'ನಿರ್ವಹಣೆ ಆನ್ ಆಗಿರುವಾಗ ಸೈನ್-ಇನ್ ಪರದೆಯಲ್ಲಿ ತೋರಿಸಲಾಗುತ್ತದೆ ಮತ್ತು ಪ್ರತಿ ಟೆನೆಂಟ್ ವಿನಂತಿಗೆ ಉತ್ತರವಾಗಿ ಕಳುಹಿಸಲಾಗುತ್ತದೆ. ಪ್ರಮಾಣಿತ ಪದಗಳಿಗಾಗಿ ಖಾಲಿ ಬಿಡಿ.',
