  'imp.password_notice':'ಪ್ರತಿ ಉದ್ಯೋಗಿಗೆ ತಾತ್ಕಾಲಿಕ ಪಾಸ್‌ವರ್ಡ್ ಸಿಗುತ್ತದೆ: ಅವರ ಹೆಸರಿನ ಮೊದಲ 4 ಅಕ್ಷರಗಳು ಮತ್ತು ಜನ್ಮ ವರ್ಷ. ಮೊದಲ ಬಾರಿ ಸೈನ್ ಇನ್ ಮಾಡುವಾಗ ಅದನ್ನು ಬದಲಾಯಿಸಬೇಕು, ಅಲ್ಲಿಯವರೆಗೆ ಬೇರೇನನ್ನೂ ಬಳಸಲಾಗುವುದಿಲ್ಲ. ಸಹೋದ್ಯೋಗಿಯ ಹೆಸರು ಮತ್ತು ಜನ್ಮ ವರ್ಷ ತಿಳಿದವರು ಇದನ್ನು ಊಹಿಸಬಹುದು, ಆದ್ದರಿಂದ ಬೇಗ ಸೈನ್ ಇನ್ ಮಾಡಿ ಬದಲಾಯಿಸಲು ತಿಳಿಸಿ.',
  'imp.skipped_rows':'ಬಿಟ್ಟುಬಿಡಲಾಗುವ ಸಾಲುಗಳು',
