  'imp.tell_employees':'ಪ್ರತಿ ಉದ್ಯೋಗಿಗೆ ಅವರ ಮೊದಲ ಪಾಸ್‌ವರ್ಡ್ ತಿಳಿಸಿ: ಅವರ ಹೆಸರಿನ ಮೊದಲ 4 ಅಕ್ಷರಗಳು (ಸಣ್ಣ ಅಕ್ಷರ) ಮತ್ತು ಜನ್ಮ ವರ್ಷ. ಉದಾ. ಆಶಾ ರಾವ್, ಜನನ 1994 → asha1994. ಸೈನ್ ಇನ್ ಮಾಡಿದ ತಕ್ಷಣ ಹೊಸ ಪಾಸ್‌ವರ್ಡ್ ಆಯ್ಕೆ ಮಾಡಲು ಕೇಳಲಾಗುತ್ತದೆ.',
