  'lb.share_saved':'ಚಿತ್ರ ಉಳಿಸಲಾಗಿದೆ — ಎಲ್ಲಿ ಬೇಕಾದರೂ ಲಗತ್ತಿಸಿ.',
  'lb.share_no_rank':'ನೀವು ಇನ್ನೂ ಈ ಪಟ್ಟಿಯಲ್ಲಿ ಇಲ್ಲ. ಪಟ್ಟಿಗೆ ಸೇರಲು ಒಂದು ಕಲ್ಪನೆ ಸಲ್ಲಿಸಿ.',
  'info.patentable':'“ಇದು ಬೌದ್ಧಿಕ ಆಸ್ತಿಯಾಗಿ ರಕ್ಷಿಸುವಷ್ಟು ಹೊಸದಿರಬಹುದು” ಎಂಬ ಅರ್ಥದ ಗುರುತು. ಯಾರಾದರೂ ತಮ್ಮದೇ ಕಲ್ಪನೆಗೆ, ಮತ್ತು ಯಾವುದೇ ಪರಿಶೀಲಕರು ಯಾವುದೇ ಕಲ್ಪನೆಗೆ ಇದನ್ನು ಹಾಕಬಹುದು. ಇದು ಹತ್ತಿರದಿಂದ ನೋಡುವ ಸೂಚನೆ ಮಾತ್ರ — ಅನುಮೋದನೆಯ ಮೇಲೆ ಪರಿಣಾಮ ಬೀರುವುದಿಲ್ಲ, ಮತ್ತು ನಿರ್ವಾಹಕರು ನಂತರ ದಾಖಲಿಸುವ ಔಪಚಾರಿಕ ಪೇಟೆಂಟ್ ನಿರ್ಧಾರಕ್ಕಿಂತ ಬೇರೆ.',
  'info.ip_address':'IP ಎಂದರೆ ಇಂಟರ್ನೆಟ್ ಪ್ರೊಟೊಕಾಲ್. IP ವಿಳಾಸವು ವಿನಂತಿ ಯಾವ ಸಂಪರ್ಕದಿಂದ ಬಂತು ಎಂಬುದನ್ನು ಗುರುತಿಸುವ ಸಂಖ್ಯೆ — ಸ್ಥೂಲವಾಗಿ ಯಾವ ಕಚೇರಿ, ಮನೆ ಅಥವಾ ಮೊಬೈಲ್ ಜಾಲ. ಅದು ವ್ಯಕ್ತಿಯಲ್ಲ; ಒಂದೇ ಕಚೇರಿ ಸಂಪರ್ಕದ ಹಿಂದಿನ ಹಲವರು ಒಂದೇ ವಿಳಾಸ ಹಂಚಿಕೊಳ್ಳುತ್ತಾರೆ.',
  'info.max_file_mb':'ನಿಮ್ಮ ಸಂಸ್ಥೆಯಲ್ಲಿ ಯಾರಾದರೂ ಒಂದು ಕಲ್ಪನೆಗೆ ಲಗತ್ತಿಸಬಹುದಾದ ಅತಿ ದೊಡ್ಡ ಕಡತ. MB ಎಂದರೆ ಮೆಗಾಬೈಟ್: ಫೋನಿನ ಚಿತ್ರ ಸಾಮಾನ್ಯವಾಗಿ 2 ರಿಂದ 5 MB. ವೇದಿಕೆಯ ಸ್ವಂತ ಗರಿಷ್ಠ ಮಿತಿ ಇದಕ್ಕಿಂತ ಮೇಲಿರುತ್ತದೆ, ಆದ್ದರಿಂದ ಇಲ್ಲಿ ದೊಡ್ಡ ಸಂಖ್ಯೆ ಹಾಕಿದರೂ ಸರ್ವರ್ ಅದಕ್ಕಿಂತ ದೊಡ್ಡ ಕಡತವನ್ನು ಸ್ವೀಕರಿಸುವುದಿಲ್ಲ.',
  'info.situation_preview':'ಲೇಖಕರೂ ಅಲ್ಲದ, ಪರಿಶೀಲಕರೂ ಅಲ್ಲದ ಸಹೋದ್ಯೋಗಿಗಳಿಗೆ ಸಮಸ್ಯೆಯ ವಿವರಣೆ ಎಷ್ಟು ಕಾಣಬೇಕು. ಅವರಿಗೆ ಮೊದಲ ಸಾಲುಗಳಷ್ಟೇ ಕಾಣುತ್ತವೆ, ಹಾಗಾಗಿ ಮೌಲ್ಯಮಾಪನಕ್ಕೆ ಮೊದಲು ಕಲ್ಪನೆಯನ್ನು ಎತ್ತಿಕೊಳ್ಳಲಾಗದು. ಇದನ್ನು ಅಕ್ಷರಗಳಲ್ಲಿ ಅಳೆಯಲಾಗುತ್ತದೆ — 180 ಎಂದರೆ ಸುಮಾರು ಒಂದೆರಡು ವಾಕ್ಯ.',
  'info.screen_protection':'ಬ್ರೌಸರ್ ಕಿಟಕಿಯಿಂದ ಗಮನ ಸರಿದ ಕ್ಷಣವೇ ಕಲ್ಪನೆಯ ಪಠ್ಯ ಮರೆಯಾಗುತ್ತದೆ — ಹೆಚ್ಚಿನ ಸ್ಕ್ರೀನ್ ಸೆರೆಹಿಡಿಯುವ ಸಾಧನಗಳು ಮೊದಲು ಮಾಡುವುದೇ ಅದನ್ನು — ಮತ್ತು ಓದುಗರ ಹೆಸರು ಪುಟದ ಮೇಲೆ ಮಸುಕಾಗಿ ಮೂಡುತ್ತದೆ, ಇದರಿಂದ ಯಾವುದೇ ಸೆರೆಹಿಡಿಯುವಿಕೆಯನ್ನು ಪತ್ತೆ ಹಚ್ಚಬಹುದು. ಮುದ್ರಿಸಿದರೆ ಕಲ್ಪನೆಗಳಲ್ಲ, ಸೂಚನೆ ಮಾತ್ರ ಮುದ್ರಣವಾಗುತ್ತದೆ. ಮಿತಿ ಸ್ಪಷ್ಟವಾಗಿರಲಿ: ಪರದೆಯ ಕಡೆ ಹಿಡಿದ ಫೋನ್ ಕ್ಯಾಮೆರಾವನ್ನು ಯಾವ ಜಾಲಪುಟವೂ ತಡೆಯಲಾರದು. ನಿಜವಾದ ರಕ್ಷಣೆ ಎಂದರೆ ಹಕ್ಕಿಲ್ಲದವರಿಗೆ ಪೂರ್ಣ ಪಠ್ಯವನ್ನು ಕಳುಹಿಸದೇ ಇರುವುದು.',
  'detail.submitted_at':'ಸಲ್ಲಿಸಿದ ದಿನಾಂಕ',
  'form.attach_too_big':'"{name}" {size} MB ಇದೆ. ಈ ಸಂಸ್ಥೆ ಪ್ರತಿ ಕಡತಕ್ಕೆ {mb} MB ಅನುಮತಿಸುತ್ತದೆ.',
  'btn.summary':'ಸಾರಾಂಶ',
  'idea.summary_only_hint':'ಒಂದು ಪುಟದ ಸಾರಾಂಶ ಡೌನ್‌ಲೋಡ್ ಮಾಡಿ. ಪೂರ್ಣ ವಿವರಣೆ ಈ ಕಲ್ಪನೆ ಸಲ್ಲಿಸಿದವರಿಗೆ ಮತ್ತು ಪರಿಶೀಲಿಸುವವರಿಗೆ ಕಾಣುತ್ತದೆ.',

