  'bulk.open':'ಗುಂಪಾಗಿ ಸಂಗ್ರಹಿಸಿ',
  'bulk.title':'ಗುಂಪಾಗಿ ಸಂಗ್ರಹಿಸಿ',
  'bulk.help_ideas':'ಶೋಧಿಸುವುದರಿಂದ ನೀವು ಏನನ್ನು ನೋಡುತ್ತಿದ್ದೀರಿ ಎಂಬುದಷ್ಟೇ ಬದಲಾಗುತ್ತದೆ. ಸಂಗ್ರಹಿಸುವುದರಿಂದ ಆಲೋಚನೆಗಳು ಎಲ್ಲರ ದೈನಂದಿನ ಪಟ್ಟಿಗಳಿಂದ ಹೊರಹೋಗುತ್ತವೆ. ಏನೂ ಅಳಿಸಲ್ಪಡುವುದಿಲ್ಲ — ಅಂಕಗಳು, ಇತಿಹಾಸ ಮತ್ತು ಉಳಿತಾಯ ಎಲ್ಲವೂ ಉಳಿಯುತ್ತವೆ.',
  'bulk.help_tickets':'ಶೋಧಿಸುವುದರಿಂದ ನೀವು ಏನನ್ನು ನೋಡುತ್ತಿದ್ದೀರಿ ಎಂಬುದಷ್ಟೇ ಬದಲಾಗುತ್ತದೆ. ಸಂಗ್ರಹಿಸುವುದರಿಂದ ಟಿಕೆಟ್‌ಗಳು ಕೆಲಸದ ಸರತಿಯಿಂದ ಹೊರಹೋಗುತ್ತವೆ. ಏನೂ ಅಳಿಸಲ್ಪಡುವುದಿಲ್ಲ, ಮತ್ತು ಯಾವುದೇ ಟಿಕೆಟ್ ಅನ್ನು ಮರಳಿ ತರಬಹುದು.',
