  'admin.max_file_mb':'ಅತಿ ದೊಡ್ಡ ಲಗತ್ತು (MB)',
  'admin.max_file_hint':'ಇಲ್ಲಿ ಯಾರಾದರೂ ಆಲೋಚನೆಗೆ ಲಗತ್ತಿಸಬಹುದಾದ ಅತಿ ದೊಡ್ಡ ಒಂದು ಕಡತ. ವೇದಿಕೆಯ ಸ್ವಂತ ಮಿತಿ ಇದಕ್ಕಿಂತ ಮೇಲಿರುತ್ತದೆ, ಆದ್ದರಿಂದ ವೇದಿಕೆ ಅನುಮತಿಸುವುದಕ್ಕಿಂತ ದೊಡ್ಡ ಸಂಖ್ಯೆ ಹಾಕಿದರೆ ಅದನ್ನು ಆ ಮಿತಿಗೆ ಇಳಿಸಲಾಗುತ್ತದೆ.',
  'admin.situation_preview':'ಸಮಸ್ಯೆಯ ಝಲಕಿನ ಉದ್ದ',
  'admin.situation_preview_hint':'ಈ ಆಲೋಚನೆಯನ್ನು ಪರಿಶೀಲಿಸದ ಸಹೋದ್ಯೋಗಿಗಳು ಸಮಸ್ಯೆಯ ವಿವರಣೆಯ ಎಷ್ಟು ಅಕ್ಷರಗಳನ್ನು ಓದಬಹುದು. ಸುಮಾರು 180 ಎಂದರೆ ಒಂದೆರಡು ವಾಕ್ಯಗಳು.',
  'admin.screen_protection':'ಪರದೆಯ ಮೇಲೆ ಆಲೋಚನೆಗಳನ್ನು ರಕ್ಷಿಸಿ',
  'admin.sp_hint':'ಕಿಟಕಿಯಿಂದ ಗಮನ ಹೊರಟ ಕೂಡಲೇ ಅಥವಾ ಪುಟ ಮುದ್ರಣವಾದಾಗ ಆಲೋಚನೆಯ ಪಠ್ಯ ಮರೆಯಾಗುತ್ತದೆ ಮತ್ತು ಓದುಗರ ಹೆಸರು ಅದರ ಮೇಲೆ ಮೂಡುತ್ತದೆ. ಇದರಿಂದ ನಕಲಿಸುವುದು ಕಷ್ಟವಾಗುತ್ತದೆ ಮತ್ತು ಯಾವುದೇ ಸೋರಿಕೆಯನ್ನು ಗುರುತಿಸಬಹುದು. ಮಾನಿಟರ್‌ನತ್ತ ತಿರುಗಿಸಿದ ಫೋನ್ ಕ್ಯಾಮೆರಾವನ್ನು ಇದು ತಡೆಯಲಾರದು — ಯಾವ ವೆಬ್ ಪುಟವೂ ತಡೆಯಲಾರದು.',
