  'admin.employee_sections':'ಬೇರೊಬ್ಬರ ಆಲೋಚನೆಯಲ್ಲಿ ಸಹೋದ್ಯೋಗಿಗಳು ಏನನ್ನು ಓದಬಹುದು',
  'admin.employee_sections_hint':'ಇದು ಆ ಆಲೋಚನೆಯ ಲೇಖಕರೂ, ಸಹ-ಸಲಹೆಗಾರರೂ, ಪರಿಶೀಲಕರೂ ಅಲ್ಲದವರಿಗೆ ಮಾತ್ರ ಅನ್ವಯಿಸುತ್ತದೆ. ಶೀರ್ಷಿಕೆ, ಕೋಡ್, ಸ್ಥಿತಿ, ವಿಭಾಗ, ಪರಿಣಾಮ ಮತ್ತು ಅಂಕ ಯಾವಾಗಲೂ ಕಾಣುತ್ತವೆ — ಅವುಗಳಿಂದಲೇ ಆಲೋಚನೆ ಸಿಗುತ್ತದೆ ಮತ್ತು ಅವನ್ನೇ ಲೀಡರ್‌ಬೋರ್ಡ್ ಎಣಿಸುತ್ತದೆ. ಲೇಖಕರು ತಮ್ಮ ಆಲೋಚನೆಯನ್ನು ಯಾವಾಗಲೂ ಪೂರ್ಣವಾಗಿ ಓದುತ್ತಾರೆ ಮತ್ತು ಪರಿಶೀಲಕರು ತಾವು ತೀರ್ಮಾನಿಸುತ್ತಿರುವುದನ್ನು ಪೂರ್ಣವಾಗಿ ಓದುತ್ತಾರೆ.',
