  'hier.lookup_hint':'ಹೆಸರು, ಉದ್ಯೋಗಿ ಸಂಖ್ಯೆ ಅಥವಾ ಇಮೇಲ್ ಟೈಪ್ ಮಾಡಲು ಆರಂಭಿಸಿ ಮತ್ತು ವ್ಯಕ್ತಿಯನ್ನು ಆರಿಸಿ. ಅವರ ಮೇಲಿನ ಎಲ್ಲರೂ ಅತ್ಯಂತ ಮೇಲಿನವರೆಗೆ, ಮತ್ತು ಅವರಿಗೆ ವರದಿ ಮಾಡುವ ಎಲ್ಲರೂ ನಿಮಗೆ ಕಾಣುತ್ತಾರೆ. ಅವರ ಆಲೋಚನೆ ಅನುಮೋದನೆಗಾಗಿ ಇದೇ ಹಾದಿಯಲ್ಲಿ ಸಾಗುತ್ತದೆ.',
