  'msgb.warn_no_plan':'{n} ಸಂಸ್ಥೆಗಳಿಗೆ ಯೋಜನೆ ನಿಗದಿಯಾಗಿಲ್ಲ.',
  'msgb.warn_no_plan_hint':'ಅವು ಯಾವುದೇ ಒಪ್ಪಿತ ಷರತ್ತುಗಳಿಲ್ಲದೆ ವೇದಿಕೆಯನ್ನು ಬಳಸುತ್ತಿವೆ. ಅವರಿಗೆ ಎಂದೂ ಏನೂ ಮುಗಿಯುವುದಿಲ್ಲ ಮತ್ತು ಎಂದೂ ಪಾವತಿ ಕೇಳಲಾಗುವುದಿಲ್ಲ. ಒಂದು ಯೋಜನೆ ನೀಡಿ, ಅಥವಾ ಉದ್ದೇಶಪೂರ್ವಕವಾಗಿ ‘ಬಿಲ್ ಇಲ್ಲ’ ಎಂದು ಇರಿಸಿ.',
  'msgb.enforce_off':'ಜಾರಿ ಆಫ್ ಆಗಿದೆ. ಅವಧಿ ಮುಗಿದ ಸಂಸ್ಥೆಗಳನ್ನು ‘ಅವಧಿ ಮುಗಿದಿದೆ’ ಎಂದು ಗುರುತಿಸಲಾಗುತ್ತದೆ ಆದರೆ ತಡೆಹಿಡಿಯಲಾಗುವುದಿಲ್ಲ, ಆದ್ದರಿಂದ ಯಾರ ಪ್ರವೇಶವೂ ಹೋಗುವುದಿಲ್ಲ. ಪಾವತಿಯಾಗದಿದ್ದಾಗ ಖಾತೆಗಳನ್ನು ತಡೆಹಿಡಿಯಲು ಸಿದ್ಧರಾದಾಗ ಸೆಟ್ಟಿಂಗ್‌ಗಳು → ಡೀಫಾಲ್ಟ್‌ನಲ್ಲಿ ಇದನ್ನು ಆನ್ ಮಾಡಿ.',
