  'msgg.endpoint_hint':'ಸಂದೇಶಗಳನ್ನು ಎಲ್ಲಿಗೆ ಕಳುಹಿಸಲಾಗುತ್ತದೆ. ಇದು https ಆಗಿರಬೇಕು — ಇಲ್ಲದಿದ್ದರೆ ಕೀ ಮತ್ತು ಸಂಖ್ಯೆ ಬಯಲಾಗಿ ಜಾಲದ ಮೇಲೆ ಹೋಗುತ್ತವೆ.',
  'msgg.template_text':'ನೋಂದಾಯಿತ ಟೆಂಪ್ಲೇಟ್‌ನ ಪದಗಳು',
  'msgg.template_text_hint':'DLT ಪೋರ್ಟಲ್‌ನಲ್ಲಿ ಅನುಮೋದನೆಯಾದಂತೆ ವಿರಾಮಚಿಹ್ನೆಗಳ ಸಹಿತ ಥೇಟ್ ಅದೇ ರೀತಿ ನಕಲಿಸಿ. {#var#} ಪ್ರತಿ ಬದಲಾಗುವ ಮೌಲ್ಯವನ್ನು ಸೂಚಿಸುತ್ತದೆ: ಮೊದಲನೆಯದು ಕೋಡ್, ಎರಡನೆಯದು ನಿಮಿಷಗಳ ಸಂಖ್ಯೆ. ಇದು ನೋಂದಾಯಿತ ಟೆಂಪ್ಲೇಟ್‌ಗೆ ಹೊಂದದಿದ್ದರೆ ಆಪರೇಟರ್ ಪ್ರತಿ ಸಂದೇಶವನ್ನೂ ಸದ್ದಿಲ್ಲದೆ ಕೈಬಿಡುತ್ತಾನೆ.',
