  'msgg.code_length_hint':'ಅಂಕಿಗಳು. ಆರು ಸಾಮಾನ್ಯ; ನಾಲ್ಕನ್ನು ಊಹಿಸುವುದು ಸುಲಭ ಮತ್ತು ಎಂಟನ್ನು ಪರದೆಯಿಂದ ಓದುವುದು ಕಷ್ಟ.',
  'msgg.ttl':'ಕೋಡ್‌ನ ಅವಧಿ (ಸೆಕೆಂಡು)',
  'msgg.ttl_hint':'ಕೋಡ್ ಎಷ್ಟು ಕಾಲ ಬಳಸಬಹುದಾಗಿರುತ್ತದೆ. ಐದು ನಿಮಿಷ ಡೀಫಾಲ್ಟ್ — ಸಂದೇಶ ಓದಿ ಟೈಪ್ ಮಾಡಲು ಸಾಕು, ಮತ್ತು ಮಧ್ಯೆ ಸಿಕ್ಕ ಕೋಡ್ ಯಾರಾದರೂ ಬಳಸುವ ಮೊದಲೇ ನಿರುಪಯುಕ್ತವಾಗುವಷ್ಟು ಕಡಿಮೆ.',
  'msgg.attempts':'ಎಷ್ಟು ತಪ್ಪು ಪ್ರಯತ್ನಗಳಿಗೆ ಅವಕಾಶ',
  'msgg.attempts_hint':'ಇಷ್ಟು ತಪ್ಪು ಉತ್ತರಗಳ ನಂತರ ಕೋಡ್ ರದ್ದಾಗುತ್ತದೆ, ಆದ್ದರಿಂದ ಆರು ಅಂಕಿಯ ಕೋಡ್ ಅನ್ನು ಜಾಲದ ವೇಗದಲ್ಲಿ ಊಹಿಸಿ ಒಡೆಯಲಾಗುವುದಿಲ್ಲ.',
  'msgg.resend':'ಮತ್ತೆ ಕಳುಹಿಸಲು ಕಾಯುವಿಕೆ (ಸೆಕೆಂಡು)',
  'msgg.resend_hint':'ಇನ್ನೊಂದು ಕೋಡ್ ಕೇಳುವ ಮೊದಲು ಎಷ್ಟು ಕಾಲ ಕಾಯಬೇಕು. ಕಾಯುವಿಕೆಯನ್ನು ಪೂರ್ತಿ ತೆಗೆಯಲು 0 ಇರಿಸಿ, ಇದು ಸಾಮಾನ್ಯವಾಗಿ ಪರೀಕ್ಷೆಯ ಸಮಯದಲ್ಲಿ ಮಾತ್ರ ಬೇಕಾಗುತ್ತದೆ.',
  'msgg.mail_title':'ZeptoMail — ವೇದಿಕೆಯ ಇಮೇಲ್',
  'msgg.mail_sub':'ಸಂಸ್ಥೆಯ ಸ್ವಂತ SMTP ಕಳುಹಿಸಲಾಗದ ಎಲ್ಲವನ್ನೂ ಇದು ಕಳುಹಿಸುತ್ತದೆ: ಇಮೇಲ್ ವಿಳಾಸಕ್ಕೆ ಕಳುಹಿಸಿದ ಕೋಡ್‌ಗಳು, ನೋಂದಣಿಯ ಸ್ವೀಕೃತಿ ಮತ್ತು ಸ್ವಂತ ಮೇಲ್ ಸರ್ವರ್ ನಿಗದಿಪಡಿಸಿಕೊಳ್ಳದ ಗ್ರಾಹಕರ ಮೇಲ್. SMTP ಕಾನ್ಫಿಗರ್ ಮಾಡಿಕೊಂಡ ಗ್ರಾಹಕ ಅದನ್ನೇ ಬಳಸುತ್ತಿರುತ್ತಾರೆ.',
