  'msgg.mail_enable_hint':'ಇದು ಆಫ್ ಆಗಿರುವವರೆಗೆ, ಸ್ವಂತ SMTP ಹೋಸ್ಟ್ ಇಲ್ಲದ ಸಂಸ್ಥೆಯ ಮೇಲ್ ಅನ್ನು ಖಂಡಿತವಾಗಿಯೂ ತಲುಪಿಸಲಾಗುವುದಿಲ್ಲ.',
  'msgg.mail_from':'ಕಳುಹಿಸುವವರ ವಿಳಾಸ',
  'msgg.mail_from_hint':'ಇದು ZeptoMail ನಲ್ಲಿ ಪರಿಶೀಲಿತ ಡೊಮೇನ್‌ನದ್ದಾಗಿರಬೇಕು ಮತ್ತು ಟೋಕನ್ ಯಾವ ಮೇಲ್ ಏಜೆಂಟ್‌ನದ್ದೋ ಅದೇ ಏಜೆಂಟ್‌ಗೆ ಸೇರಿರಬೇಕು. ಪರಿಶೀಲನೆಯಾಗದ ಕಳುಹಿಸುವವರು ಮೊದಲ ಬಾರಿಯ ಅತಿ ಸಾಮಾನ್ಯ ವೈಫಲ್ಯ.',
  'msgg.mail_from_name':'ಕಳುಹಿಸುವವರ ಹೆಸರು',
  'msgg.mail_from_name_hint':'ಸ್ವೀಕರಿಸುವವರಿಗೆ ಕಳುಹಿಸಿದವರ ಹೆಸರಾಗಿ ಕಾಣುವುದು ಇದೇ.',
  'msgg.mail_endpoint':'ಡೇಟಾ ಸೆಂಟರ್',
  'msgg.mail_endpoint_hint':'ನಿಮ್ಮ Zoho ಖಾತೆ ಸೃಷ್ಟಿಯಾದ ಪ್ರದೇಶಕ್ಕೆ ಇದು ಹೊಂದಬೇಕು. ಒಂದು ಪ್ರದೇಶದ ಟೋಕನ್ ಇನ್ನೊಂದರಲ್ಲಿ 401 ನೀಡುತ್ತದೆ ಮತ್ತು ಆ ದೋಷದಲ್ಲಿ ಪ್ರದೇಶದ ಪ್ರಸ್ತಾಪವೇ ಇರುವುದಿಲ್ಲ.',
  'msgg.mail_token':'Send Mail ಟೋಕನ್',
  'msgg.mail_token_stored':'ಒಂದು ಟೋಕನ್ ಉಳಿಸಲಾಗಿದೆ. ಅದನ್ನೇ ಉಳಿಸಿಕೊಳ್ಳಲು ಇದನ್ನು ಖಾಲಿ ಬಿಡಿ; ಬದಲಿಸಲು ಹೊಸದನ್ನು ಅಂಟಿಸಿ.',
  'msgg.mail_token_none':'ಇನ್ನೂ ಯಾವುದೇ ಟೋಕನ್ ಉಳಿಸಿಲ್ಲ. ನಿಮ್ಮ ZeptoMail ಮೇಲ್ ಏಜೆಂಟ್‌ನಿಂದ Send Mail ಟೋಕನ್ ಅಂಟಿಸಿ.',
