  'msgg.mail_token_clear':'ಸಂಗ್ರಹಿಸಿದ ಟೋಕನ್ ತೆಗೆದುಹಾಕಿ',
  'msgg.mail_otp':'ಇಮೇಲ್ ಮೂಲಕ ಸೈನ್-ಇನ್ ಕೋಡ್‌ಗೆ ಅವಕಾಶ ನೀಡಿ',
  'msgg.mail_otp_hint':'ಇಮೇಲ್ ವಿಳಾಸದಿಂದ ಸೈನ್ ಇನ್ ಮಾಡುವವರಿಗೆ ಸಂದೇಶದ ಬದಲು ಇಮೇಲ್‌ನಲ್ಲಿ ಕೋಡ್ ಸಿಗುವಂತೆ ಮಾಡುತ್ತದೆ. ಇದಿಲ್ಲದೆ ಇಮೇಲ್ ಸೈನ್-ಇನ್‌ಗೆ ಯಾವ ಕೋಡ್ ಕೂಡ ಸಿಗುವುದಿಲ್ಲ.',
  'msgg.mail_test_btn':'ಪರೀಕ್ಷಾ ಇಮೇಲ್ ಕಳುಹಿಸಿ',
  'msgg.mail_test_ok':'ZeptoMail ಸ್ವೀಕರಿಸಿದೆ',
  'msgg.mail_test_fail':'ZeptoMail ನಿರಾಕರಿಸಿದೆ',
  'msgg.email_title':'ಇಮೇಲ್ ಸರತಿ',
  'msgg.email_hint':'ಸೂಚನಾ ಇಮೇಲ್‌ಗಳನ್ನು ಪ್ರತಿ ಸಂಸ್ಥೆಯ ಸ್ವಂತ ಡೇಟಾಬೇಸ್‌ನಲ್ಲಿ ಸರತಿಯಲ್ಲಿ ಇರಿಸಲಾಗುತ್ತದೆ ಮತ್ತು ಹಿನ್ನೆಲೆ ಕಾರ್ಯ ಅವನ್ನು ಕಳುಹಿಸುತ್ತದೆ. ಪಾಸ್‌ವರ್ಡ್ ಮರುಹೊಂದಿಕೆ ಮತ್ತು ಸಹಾಯದ ಉತ್ತರಗಳು ನೇರವಾಗಿ ಕಳುಹಿಸಲ್ಪಡುತ್ತವೆ ಮತ್ತು ಇಲ್ಲಿ ಕಾಣಿಸುವುದಿಲ್ಲ.',
  'msgg.email_pending':'ಕಳುಹಿಸಲು ಕಾಯುತ್ತಿವೆ',
