  'lb.email_more':'…ಮತ್ತು ಪೂರ್ಣ ಪಟ್ಟಿಯಲ್ಲಿ ಇನ್ನೂ {n} ಮಂದಿ.',
  'lb.email_footer':'IFQM ಉದ್ಯೋಗಿ ಐಡಿಯೇಶನ್ ಟೂಲ್‌ನಿಂದ ಕಳುಹಿಸಲಾಗಿದೆ.',
  'login.otp_id_ph':'ಬಳಕೆದಾರ ಹೆಸರು, ನೋಂದಾಯಿತ ಇಮೇಲ್ ಅಥವಾ ಮೊಬೈಲ್ ಸಂಖ್ಯೆ',
  'login.reset_code_sent':'ಅದು ನಮ್ಮಲ್ಲಿ ನೋಂದಾಯಿತವಾಗಿದ್ದರೆ, ಕೋಡ್ ಕಳುಹಿಸಲಾಗಿದೆ. ಹೊಸ ಪಾಸ್‌ವರ್ಡ್ ಹೊಂದಿಸಲು ಅದನ್ನು ಸೈನ್-ಇನ್ ಪರದೆಯಲ್ಲಿ ನಮೂದಿಸಿ.',
  'login.reset_code_sent_to':'{where} ಗೆ ಕೋಡ್ ಕಳುಹಿಸಲಾಗಿದೆ. ಹೊಸ ಪಾಸ್‌ವರ್ಡ್ ಹೊಂದಿಸಲು ಅದನ್ನು ಸೈನ್-ಇನ್ ಪರದೆಯಲ್ಲಿ ನಮೂದಿಸಿ.',
  'admin.uf_phone_required':'ಪ್ರತಿ ಬಳಕೆದಾರರಿಗೂ ಮೊಬೈಲ್ ಸಂಖ್ಯೆ ಅಗತ್ಯ.',
  'admin.uf_phone_invalid':'ದೇಶ ಅಥವಾ ಪ್ರದೇಶ ಕೋಡ್ ಸಹಿತ ಮಾನ್ಯ ಮೊಬೈಲ್ ಸಂಖ್ಯೆ ನಮೂದಿಸಿ.',
  'admin.uf_username':'ಬಳಕೆದಾರ ಹೆಸರು',
  'admin.uf_username_ph':'ಉದಾ. yashas123',
  'admin.uf_login_hint':'ಬಳಕೆದಾರ ಹೆಸರು ಅಥವಾ ಇಮೇಲ್ ವಿಳಾಸ ನೀಡಿ — ಕನಿಷ್ಠ ಒಂದು, ಏಕೆಂದರೆ ಅದರಿಂದಲೇ ವ್ಯಕ್ತಿ ಸೈನ್ ಇನ್ ಮಾಡುತ್ತಾರೆ. ಬಳಕೆದಾರ ಹೆಸರು 3–30 ಅಕ್ಷರಗಳು (ಅಕ್ಷರ, ಸಂಖ್ಯೆ, ಚುಕ್ಕೆ, ಅಂಡರ್‌ಸ್ಕೋರ್, ಹೈಫನ್) ಮತ್ತು ಇಡೀ ವೇದಿಕೆಯಲ್ಲಿ ಅನನ್ಯವಾಗಿರಬೇಕು.',
